using System;
using System.Collections.Generic;
using System.Reflection;
using GameplayTags;
internal static class Program
{
 static readonly FieldInfo Buckets=typeof(TagStorage).GetField("m_Buckets",BindingFlags.NonPublic|BindingFlags.Instance), Mask=typeof(TagStorage).GetField("m_BucketMask",BindingFlags.NonPublic|BindingFlags.Instance);
 static GameplayTag[] Flat,Deep;static GameplayTag Other;static IGameplayTagContainer Legacy;static int Cases,Admitted,Fallback;
 sealed class NormalView:GameplayTagContainer,IGameplayTagContainer{readonly IGameplayTagContainer inner;internal NormalView(IGameplayTagContainer x){inner=x;}GameplayTagContainerIndices IGameplayTagContainer.Indices=>inner.Indices;}
 static void Register(){var regs=new List<GameplayTagRegistration>();for(int i=0;i<2048;i++)regs.Add(new GameplayTagRegistration("F.G"+(i%13)+".L"+i));var n=new string[1100];n[0]="Deep";for(int i=1;i<n.Length;i++)n[i]=n[i-1]+".N";regs.Add(new GameplayTagRegistration(n[n.Length-1]));string other="Other";for(int i=1;i<2300;i++)other+=".N";regs.Add(new GameplayTagRegistration(other));regs.Add(new GameplayTagRegistration("Keep"));regs.Add(new GameplayTagRegistration("Wrapped"));for(int i=0;i<1023;i++)regs.Add(new GameplayTagRegistration("Fill"+i));GameplayTagManager.Initialize(regs.ToArray());Other=GameplayTagManager.RequestTag(other);Flat=new GameplayTag[2048];for(int i=0;i<Flat.Length;i++)Flat[i]=GameplayTagManager.RequestTag("F.G"+(i%13)+".L"+i);Deep=Array.ConvertAll(n,GameplayTagManager.RequestTag);var c=new GameplayTagCountContainer();c.AddTag(GameplayTagManager.RequestTag("Keep"));for(int i=0;i<1023;i++)c.AddTag(GameplayTagManager.RequestTag("Fill"+i));var w=GameplayTagManager.RequestTag("Wrapped");c.AddTag(w,int.MaxValue);c.AddTag(w,int.MaxValue);c.AddTag(w,2);c.AddTag(w,1);c.RemoveTag(w,1);for(int i=1022;i>=0;i--)c.RemoveTag(GameplayTagManager.RequestTag("Fill"+i));Legacy=new NormalView(c);}
 static GameplayTag At(int e,int shape,int i){return shape==0?Flat[i]:Deep[shape==1?i:e-1-i];}
 static GameplayTagContainer MakeOutput(int e,int shape,int reserve,bool history){var c=new GameplayTagContainer(reserve);if(history){c.AddTag(Other);foreach(var t in Flat)c.AddTag(t);var small=new GameplayTagContainer();small.AddTag(Flat[0]);GameplayTagContainer.Copy(c,small);c.Clear();}for(int i=0;i<e;i++)c.AddTag(At(e,shape,i));c.m_SerializedExplicitTags=new List<string>(17){"stale","cache"};return c;}
 static GameplayTagContainer MakeSeed(int e,int shape,int overlap){var c=new GameplayTagContainer(32768);c.AddTag(Other);for(int i=0;i<e*overlap/100;i++)c.AddTag(At(e,shape,i));c.m_SerializedExplicitTags=new List<string>(17){"seed","cache"};return c;}
 static object[] Refs(GameplayTagContainer c){var s=c.Indices.Storage;return new object[]{s,s.Entries,s.ExplicitIndices,Buckets.GetValue(s),c.m_SerializedExplicitTags};}
 static string Identity(object[] before,GameplayTagContainer c){var after=Refs(c);var result="";for(int i=0;i<before.Length;i++)result+=ReferenceEquals(before[i],after[i])?"S":"C";return result;}
 static string Diff(GameplayTagContainer a,GameplayTagContainer b){var x=a.Indices.Storage;var y=b.Indices.Storage;if(x.Count!=y.Count||x.ExplicitCount!=y.ExplicitCount||(int)Mask.GetValue(x)!=(int)Mask.GetValue(y))return "counts/mask";if(x.Entries.Length!=y.Entries.Length)return "entry length";for(int i=0;i<x.Entries.Length;i++){var p=x.Entries[i];var q=y.Entries[i];if(p.Id!=q.Id||p.Count!=q.Count||p.ExplicitCount!=q.ExplicitCount||p.ExplicitIndex!=q.ExplicitIndex)return "entry "+i+" of "+x.Count;}if(x.ExplicitIndices.Length!=y.ExplicitIndices.Length)return "explicit length";for(int i=0;i<x.ExplicitIndices.Length;i++)if(x.ExplicitIndices[i]!=y.ExplicitIndices[i])return "explicit "+i+" of "+x.ExplicitCount;var xb=(int[])Buckets.GetValue(x);var yb=(int[])Buckets.GetValue(y);if(xb.Length!=yb.Length)return "bucket length";for(int i=0;i<xb.Length;i++)if(xb[i]!=yb[i])return "bucket "+i;if(a.m_SerializedExplicitTags.Count!=b.m_SerializedExplicitTags.Count||a.m_SerializedExplicitTags.Capacity!=b.m_SerializedExplicitTags.Capacity)return "cache";return null;}
 static void Run(int e,int shape,int reserve,bool history,int overlap,bool aliasLeft){var expected=MakeOutput(e,shape,reserve,history);var actual=MakeOutput(e,shape,reserve,history);var es=MakeSeed(e,shape,overlap);var a=MakeSeed(e,shape,overlap);string id=e+"/"+shape+"/"+reserve+"/"+history+"/"+overlap+"/"+aliasLeft;if(a.TagCount<=actual.TagCount)throw new Exception("non-opposite setup");if(!a.Indices.Storage.CanReuseSelectedUnionSeed(actual.Indices.Storage))throw new Exception("healthy admission rejected");if(e<=1024)Admitted++;else Fallback++;var er=Refs(expected);var ar=Refs(actual);var esr=Refs(es);var asr=Refs(a);if(aliasLeft){GameplayTagContainer.Copy(expected,GameplayTagContainer.Union(expected,es));GameplayTagContainer.Union(actual,actual,a);}else{GameplayTagContainer.Copy(expected,GameplayTagContainer.Union(es,expected));GameplayTagContainer.Union(actual,a,actual);}var diff=Diff(expected,actual);if(diff!=null)throw new Exception(id+" union: "+diff);if(Identity(er,expected)!=Identity(ar,actual))throw new Exception(id+" identity mismatch");if(Diff(es,a)!=null||Identity(esr,es)!=Identity(asr,a))throw new Exception(id+" selected source mutation");for(int i=0;i<8;i++){expected.AddTag(Flat[2000+i]);actual.AddTag(Flat[2000+i]);expected.RemoveTag(Flat[2000+i]);actual.RemoveTag(Flat[2000+i]);if(Diff(expected,actual)!=null)throw new Exception(id+" add/remove continuation");}GameplayTagContainer.Copy(expected,Legacy);GameplayTagContainer.Copy(actual,Legacy);if(Diff(expected,actual)!=null)throw new Exception(id+" stale public Copy continuation");expected.Clear();actual.Clear();expected.AddTag(Deep[100]);actual.AddTag(Deep[100]);if(Diff(expected,actual)!=null)throw new Exception(id+" clear/regrow continuation");Cases++;}
 static void Main(){Register();foreach(int e in new[]{0,1,8,9,15,16,17,127,128,129,1023,1024,1025})foreach(int reserve in new[]{0,8192})foreach(bool history in new[]{false,true})foreach(int overlap in new[]{0,50,100})foreach(bool left in new[]{false,true})Run(e,0,reserve,history,overlap,left);foreach(int e in new[]{9,128,1024,1025})foreach(int shape in new[]{1,2})foreach(int reserve in new[]{0,8192})foreach(bool history in new[]{false,true})foreach(int overlap in new[]{0,100})foreach(bool left in new[]{false,true})Run(e,shape,reserve,history,overlap,left);Console.WriteLine("PASS opposite-seed API: "+Cases+" full-owned-state/identity/source-immutability/legacy-Copy/mutation cases; "+Admitted+" bounded admissions; "+Fallback+" E1025 fallbacks; no timing");}
}
